import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Metering and cost","description":"","frontmatter":{},"headers":[],"relativePath":"components/metering.md","filePath":"components/metering.md"}`),a={name:`components/metering.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="metering-and-cost" tabindex="-1">Metering and cost <a class="header-anchor" href="#metering-and-cost" aria-label="Permalink to “Metering and cost”">​</a></h1><h2 id="the-principle-bill-what-vendors-bill-you" tabindex="-1">The principle: bill what vendors bill you <a class="header-anchor" href="#the-principle-bill-what-vendors-bill-you" aria-label="Permalink to “The principle: bill what vendors bill you”">​</a></h2><p>Metering is pass-through cost attribution, not a token-count product. A turn produces vendor cost lines — LLM tokens by bucket per model, speech-to-text seconds, paid lookups — each priced at the endpoint&#39;s own rate (<code>LLM_&lt;NAME&gt;_PRICE</code>, <code>AGENT_STT_PRICE_PER_MIN</code>). Work served from your own infrastructure costs nothing and is recorded as such: a prompt-cache hit is billed at the provider&#39;s cache-read rate because the provider bills it; a runtime-answered turn (no model call) is free; a semantic cache you built yourself is free.</p><h2 id="the-unit-users-see-a-percentage" tabindex="-1">The unit users see: a percentage <a class="header-anchor" href="#the-unit-users-see-a-percentage" aria-label="Permalink to “The unit users see: a percentage”">​</a></h2><p>Users never see tokens, and never &quot;N things left&quot; (a job&#39;s cost varies 2–5× with how it goes). Caps count <strong>plan tokens</strong> — a cost-weighted token count (fresh input 1, cached read 0.1, output 6, cache write 1 by default: a typical primary model&#39;s price ratios) — because measured on real chats it tracks the bill with r = 1.00 where raw totals varied 2.4× and billable-only counts 8.9×. The widget shows &quot;Daily · 33% used · resets in 24h&quot;. Weights are environment (<code>AGENT_PLAN_WEIGHT_*</code>), fixed to the primary model so a failover premium is never charged to the user.</p><h2 id="where-the-numbers-live" tabindex="-1">Where the numbers live <a class="header-anchor" href="#where-the-numbers-live" aria-label="Permalink to “Where the numbers live”">​</a></h2><ul><li><strong>Per call</strong>: the chain tags each model reply with provider, model and USD cost (price table or override); the <code>chat</code> span carries <code>gen_ai.usage.*</code> and <code>gen_ai.usage.cost</code>.</li><li><strong>Per session</strong>: <code>session.usage</code> (four buckets, calls, turns, cost_usd, last provider/model).</li><li><strong>Per turn</strong>: <code>usage_events</code> ledger (Mongo or JSONL under <code>.data/ledger/</code>): tokens, plan tokens, cost, provider, model, tool calls, whether the runtime answered.</li><li><strong>Caps</strong>: Redis fixed windows (5h / day / week) + a calendar month per subject (the verified user id hashed, else the session) — <code>usage-caps.ts</code>.</li><li><strong>A metering service</strong> (optional): <code>AGENT_METERING_URL</code> makes the gateway POST batched events through <code>@marg-adk/metering</code> — buffered, idempotent (<code>event_id = session:turn:kind</code>), fail-open; <code>check(account)</code> on the hot path bounded to 300 ms. The service rates events against a catalogue, keeps a durable ledger, and feeds a billing engine (plans, wallets, invoices) — e.g. Lago (AGPL, self-hosted) — never the agent.</li></ul><h2 id="rules-for-emitters" tabindex="-1">Rules for emitters <a class="header-anchor" href="#rules-for-emitters" aria-label="Permalink to “Rules for emitters”">​</a></h2><ul><li>No PII, no content in events — opaque ids and enums only; events are retained for years.</li><li>A deterministic <code>event_id</code> wherever your code may retry.</li><li>Omit <code>vendor_cost</code> when no third party charged for the work.</li><li>One event per token bucket per model call when you need per-model invoices; one per turn when a blended rate is enough.</li></ul><h2 id="cost-levers-in-order-of-effect" tabindex="-1">Cost levers, in order of effect <a class="header-anchor" href="#cost-levers-in-order-of-effect" aria-label="Permalink to “Cost levers, in order of effect”">​</a></h2><ol><li>The cached prefix dominates: keep the system prompt byte-identical per domain × type.</li><li>Load only the in-play variant&#39;s skills and tools (the typed prompt): −56% prompt size.</li><li>A typed decision instead of a model call wherever a decision will do (routing, readers).</li><li>Runtime-owned steps: a tap read in code costs no tokens at all.</li><li>Two-stage tool-output trimming; tool results re-fetched on demand.</li><li>Compare models on blended ₹/$ per million under YOUR prefix profile, never list price.</li></ol><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/METERING.md">docs/METERING.md</a> — edit it there; the site mirrors the repository.</small></p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};